cd __RIG_HOME__/research/base-edit-immune-aging && python3 - <<'EOF'
import json, glob
for f in sorted(glob.glob('search/*.json')):
    try:
        d = json.load(open(f))
    except Exception as e:
        print(f, 'UNPARSEABLE', e); continue
    recs = d.get('records', d) if isinstance(d, dict) else d
    prov = d.get('provenance', {}) if isinstance(d, dict) else {}
    print(f"== {f}  n_records={len(recs)}")
    if prov: print("   provenance:", json.dumps(prov)[:220])
    for r in recs[:8]:
        t = (r.get('title') or '')[:120]
        print(f"   - {r.get('year')} | {t} | PMID {r.get('pmid')}")
EOF
